const rows = items.map(i => i.json).filter(r => Object.keys(r || {}).length);
const norm = v => String(v ?? '').trim().toUpperCase();
const clean = v => String(v ?? '').trim();

const gated = rows.filter(r =>
  norm(r.ESTADO) === 'PUBLICADO' &&
  norm(r.PUBLICAR) === 'SI' &&
  norm(r.PRIVACIDAD) === 'PUBLICO'
);

const required = ['ID_NOTICIA','FECHA','SLUG','TITULO','RESUMEN'];
const invalid = gated.filter(r => required.some(k => !clean(r[k])));
if (invalid.length) {
  throw new Error(`Hay ${invalid.length} fila(s) publicables con campos obligatorios vacíos. No se modifica GitHub.`);
}

const ids = new Set();
const slugs = new Set();
for (const r of gated) {
  const id = clean(r.ID_NOTICIA);
  const slug = clean(r.SLUG);
  if (ids.has(id)) throw new Error(`ID_NOTICIA duplicado: ${id}`);
  if (slugs.has(slug)) throw new Error(`SLUG duplicado: ${slug}`);
  ids.add(id);
  slugs.add(slug);
}

function dateKey(v) {
  const s = clean(v);
  const iso = Date.parse(s);
  if (!Number.isNaN(iso)) return iso;
  const m = s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/);
  if (m) return new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1])).getTime();
  return 0;
}

const safeItems = gated.map(r => ({
  id: clean(r.ID_NOTICIA),
  fecha: clean(r.FECHA),
  slug: clean(r.SLUG),
  titulo: clean(r.TITULO),
  resumen: clean(r.RESUMEN),
  cuerpo: clean(r.CUERPO),
  imagen_ref: clean(r.IMAGEN_REF)
})).sort((a,b) => dateKey(b.fecha) - dateKey(a.fecha));

const doc = {
  schema_version: '1.0',
  generated_at: new Date().toISOString(),
  source: 'SIM_WEB_NOTICIAS',
  items: safeItems
};

const text = JSON.stringify(doc, null, 2) + '\n';

return [{json:{
  total_rows: rows.length,
  published_rows: safeItems.length,
  discarded_rows: rows.length - gated.length,
  gate: 'ESTADO=PUBLICADO && PUBLICAR=SI && PRIVACIDAD=PUBLICO',
  payload_text: text,
  content_b64: Buffer.from(text, 'utf8').toString('base64')
}}];

const build = $('Filter + Build Public JSON').first().json;
const currentRaw = ($json.content || '').replace(/\n/g, '');
let currentText = '';
try { currentText = Buffer.from(currentRaw, 'base64').toString('utf8'); } catch (e) {}

let same = false;
try {
  const a = JSON.parse(currentText || '{}');
  const b = JSON.parse(build.payload_text || '{}');
  delete a.generated_at;
  delete b.generated_at;
  same = JSON.stringify(a) === JSON.stringify(b);
} catch (e) {}

return [{json:{
  changed: !same,
  current_sha: $json.sha || '',
  content_b64: build.content_b64,
  total_rows: build.total_rows,
  published_rows: build.published_rows,
  discarded_rows: build.discarded_rows
}}];

const build = $('Filter + Build Public JSON').first().json;
const updated = Boolean($json && $json.commit && $json.commit.sha);
return [{json:{
  TIMESTAMP: new Date().toISOString(),
  RUN_ID: 'LAB-' + Date.now(),
  AMBIENTE: 'LAB',
  BRANCH: 'portal-shell-v6',
  PATH: 'preview-v6/data/noticias.json',
  TOTAL_FILAS: build.total_rows,
  PUBLICADAS: build.published_rows,
  DESCARTADAS: build.discarded_rows,
  RESULTADO: updated ? 'UPDATED' : 'NO_CHANGES',
  COMMIT_SHA: updated ? $json.commit.sha : '',
  EJECUTADO_POR: 'n8n',
  DETALLE: updated ? 'Proyección pública actualizada' : 'Sin cambios de contenido público'
}}];
